package me.eiakoji.integration.operations;

import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicLong;
import java.util.logging.Level;
import java.util.logging.Logger;

/**
 * Enterprise Integration Operations, Observability, and Governance Control Plane.
 * Implements W3C OpenTelemetry context propagation, non-blocking Wire Taps,
 * dynamic Detour routing, and rate-limited DLQ redrive.
 */
public final class IntegrationOperationsPlane {

    private static final Logger log = Logger.getLogger(IntegrationOperationsPlane.class.getName());

    // -------------------------------------------------------------------------
    // 1. Immutable Data Model & W3C Trace Record
    // -------------------------------------------------------------------------
    public record MessageRecord(
        String id,
        Map<String, String> headers,
        byte[] payload,
        Instant timestamp
    ) {
        public MessageRecord {
            headers = Map.copyOf(headers);
            payload = payload.clone();
        }

        public MessageRecord withHeader(String key, String value) {
            Map<String, String> updated = new HashMap<>(headers);
            updated.put(key, value);
            return new MessageRecord(id, updated, payload, timestamp);
        }
    }

    // -------------------------------------------------------------------------
    // 2. OpenTelemetry W3C Trace Context Propagator
    // -------------------------------------------------------------------------
    public static final class W3CTraceContextPropagator {
        public static final String TRACEPARENT_HEADER = "traceparent";
        public static final String TRACESTATE_HEADER = "tracestate";

        public record TraceContext(String traceId, String spanId, boolean sampled) {
            public String toTraceParent() {
                return String.format("00-%s-%s-%s", traceId, spanId, sampled ? "01" : "00");
            }
        }

        public static MessageRecord inject(MessageRecord record, TraceContext context) {
            return record.withHeader(TRACEPARENT_HEADER, context.toTraceParent());
        }

        public static Optional<TraceContext> extract(MessageRecord record) {
            String header = record.headers().get(TRACEPARENT_HEADER);
            if (header == null || !header.startsWith("00-")) {
                return Optional.empty();
            }
            String[] parts = header.split("-");
            if (parts.length < 4) {
                return Optional.empty();
            }
            String traceId = parts[1];
            String spanId = parts[2];
            boolean sampled = "01".equals(parts[3]);
            return Optional.of(new TraceContext(traceId, spanId, sampled));
        }
    }

    // -------------------------------------------------------------------------
    // 3. Asynchronous Non-Blocking Wire Tap
    // -------------------------------------------------------------------------
    public static final class AsynchronousWireTap implements AutoCloseable {
        private final BlockingQueue<MessageRecord> ringBuffer;
        private final ExecutorService consumerExecutor;
        private final AtomicLong droppedMessages = new AtomicLong(0);
        private final AtomicLong tappedMessages = new AtomicLong(0);
        private final java.util.function.Consumer<MessageRecord> auditSink;
        private volatile boolean running = true;

        public AsynchronousWireTap(int capacity, java.util.function.Consumer<MessageRecord> auditSink) {
            this.ringBuffer = new ArrayBlockingQueue<>(capacity);
            this.auditSink = Objects.requireNonNull(auditSink);
            this.consumerExecutor = Executors.newVirtualThreadPerTaskExecutor();
            this.consumerExecutor.submit(this::drainLoop);
        }

        public void tap(MessageRecord record) {
            // Non-blocking offer: Drop-on-full protects primary pipeline SLA
            if (!ringBuffer.offer(record)) {
                droppedMessages.incrementAndGet();
                log.log(Level.WARNING, "WireTap ring buffer saturated. Dropping audit record: {0}", record.id());
            } else {
                tappedMessages.incrementAndGet();
            }
        }

        private void drainLoop() {
            while (running || !ringBuffer.isEmpty()) {
                try {
                    MessageRecord record = ringBuffer.poll(100, TimeUnit.MILLISECONDS);
                    if (record != null) {
                        auditSink.accept(record);
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                } catch (Exception e) {
                    log.log(Level.SEVERE, "Error executing audit sink dispatch", e);
                }
            }
        }

        public long getDroppedCount() { return droppedMessages.get(); }
        public long getTappedCount() { return tappedMessages.get(); }

        @Override
        public void close() {
            this.running = false;
            this.consumerExecutor.shutdown();
            try {
                if (!consumerExecutor.awaitTermination(3, TimeUnit.SECONDS)) {
                    consumerExecutor.shutdownNow();
                }
            } catch (InterruptedException e) {
                consumerExecutor.shutdownNow();
                Thread.currentThread().interrupt();
            }
        }
    }

    // -------------------------------------------------------------------------
    // 4. Control Bus & Dynamic Detour Router
    // -------------------------------------------------------------------------
    public static final class ControlBusCoordinator {
        public enum CommandType { ACTIVATE_DETOUR, DEACTIVATE_DETOUR, REDRIVE_DLQ }
        public record AdminCommand(CommandType type, String correlationId, Map<String, String> parameters) {}

        private final AtomicBoolean detourActive = new AtomicBoolean(false);
        private final BlockingQueue<MessageRecord> deadLetterQueue = new LinkedBlockingQueue<>();
        private final BlockingQueue<MessageRecord> primaryQueue = new LinkedBlockingQueue<>();

        public void processAdminCommand(AdminCommand command) {
            switch (command.type()) {
                case ACTIVATE_DETOUR -> {
                    detourActive.set(true);
                    log.info("ControlBus: Dynamic Detour ACTIVATED by command: " + command.correlationId());
                }
                case DEACTIVATE_DETOUR -> {
                    detourActive.set(false);
                    log.info("ControlBus: Dynamic Detour DEACTIVATED by command: " + command.correlationId());
                }
                case REDRIVE_DLQ -> {
                    int maxRate = Integer.parseInt(command.parameters().getOrDefault("maxRate", "10"));
                    executeRateLimitedRedrive(maxRate);
                }
            }
        }

        public void routeMessage(MessageRecord record) {
            if (detourActive.get()) {
                executeDiagnosticDetour(record);
            } else {
                executeNormalPipeline(record);
            }
        }

        private void executeNormalPipeline(MessageRecord record) {
            primaryQueue.offer(record);
            log.fine("Normal pipeline routed: " + record.id());
        }

        private void executeDiagnosticDetour(MessageRecord record) {
            // Add detour routing breadcrumb to message history
            MessageRecord stamped = record.withHeader("X-Routing-Detour", Instant.now().toString());
            primaryQueue.offer(stamped);
            log.info("Diagnostic detour inspected and forwarded: " + record.id());
        }

        private void executeRateLimitedRedrive(int maxMessagesPerSecond) {
            long delayMs = 1000L / Math.max(1, maxMessagesPerSecond);
            Thread.startVirtualThread(() -> {
                int redriven = 0;
                MessageRecord dlqItem;
                while ((dlqItem = deadLetterQueue.poll()) != null) {
                    primaryQueue.offer(dlqItem);
                    redriven++;
                    try {
                        Thread.sleep(Duration.ofMillis(delayMs));
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        break;
                    }
                }
                log.info("ControlBus: DLQ Redrive complete. Replayed " + redriven + " messages.");
            });
        }

        public void enqueueDeadLetter(MessageRecord record) {
            deadLetterQueue.offer(record);
        }

        public boolean isDetourActive() { return detourActive.get(); }
        public int getPrimaryQueueSize() { return primaryQueue.size(); }
        public int getDeadLetterQueueSize() { return deadLetterQueue.size(); }
    }
}
